  'Ware grootte': 'Fíormhéid',
  'Pagina-einden gelden alleen op paginabreedte.':
      'Ní bhaineann briseadh leathanaigh ach le leithead leathanaigh.',
  'Hoe breed de leeskolom in de visuele modus is. Smal leest rustig, breed gebruikt meer van het scherm. Of je op die kolom, op paginabreedte of op het hele venster schrijft, kies je in de werkbalk.':
      'Cé chomh leathan is atá an colún léitheoireachta sa mhód amhairc. Léitear colún caol go socair, úsáideann colún leathan níos mó den scáileán. Roghnaítear sa bharra uirlisí an scríobhann tú ar an gcolún sin, ar leithead leathanaigh nó ar an bhfuinneog iomlán.',
  'De sprong "{doel}" wijst naar een dia die niet meer bestaat; tijdens het presenteren gebeurt er niets. Kies een andere doeldia.':
      'Tagraíonn an léim "{doel}" do sleamhnán nach ann dó a thuilleadh; ní tharlaíonn aon rud le linn an chur i láthair. Roghnaigh sprioc-sleamhnán eile.',
  'In een cirkel': 'Ciorcal',
  'Onder elkaar': 'Liosta',
  'Categorie': 'Catagóir',
  'Categorie toevoegen': 'Cuir catagóir leis',
  'Categorie opheffen (blokken blijven behouden)':
      'Bain an chatagóir (coinnítear na bloic)',
  'Uitleg': 'Cur síos',
  'Een keuzemenu: elk blok springt bij aanklikken naar een andere dia. Typ per blok een label en een uitleg, kies de doeldia en eventueel een afbeelding. Kies de indeling: raster, onder elkaar of in een cirkel. Met categorieën wissel je tijdens het presenteren tussen groepen blokken. Een blok zonder doel is gewone tekst.':
      'Roghchlár roghanna: léimeann gach bloc go sleamhnán eile nuair a chliceáiltear air. Cuir lipéad agus cur síos isteach do gach bloc, roghnaigh an sleamhnán sprice agus íomhá más mian leat. Roghnaigh an leagan amach: greille, liosta nó ciorcal. Le catagóirí athraíonn tú idir grúpaí bloc le linn an chur i láthair. Is gnáththéacs é bloc gan sprioc.',
  'Alleen een lege dia.': 'Sleamhnán folamh amháin.',
  'Hoofdstukken op nieuwe pagina': 'Caibidlí ar leathanach nua',
  'Elk hoofdstuk begint nu op een nieuwe pagina':
      'Tosaíonn gach caibidil ar leathanach nua anois',
  'Elk hoofdstuk begon al op een nieuwe pagina':
      'Thosaigh gach caibidil ar leathanach nua cheana féin',
  'Snijtekens': 'Marcanna bearrtha',
  'Alleen in de LaTeX/PDF-export, en alleen met afloop. Vereist het crop-pakket in je TeX-installatie; een browser-afdruk van de HTML-export zet ze niet.':
      'San easpórtáil LaTeX/PDF amháin, agus le fuiliú amháin. Tá an pacáiste crop de dhíth i do shuiteáil TeX; ní chuireann priontáil na heaspórtála HTML ó bhrabhsálaí isteach iad.',
  'Deze paginaopmaak staat in dit document':
      'Tá socrú an leathanaigh seo stóráilte sa cháipéis seo',
  'Deze paginaopmaak komt uit je instellingen':
      'Tagann socrú an leathanaigh seo ó do chuid socruithe',
  'Paginaopmaak': 'Socrú leathanaigh',
  'De paginamaat en marges staan nu in dit document; wie het opent krijgt dezelfde pagina. Haal ze eruit om je eigen instelling te laten gelden.':
      'Tá méid an leathanaigh agus na himill stóráilte sa cháipéis seo anois; gheobhaidh gach duine a osclóidh í an leathanach céanna. Bain amach iad chun go mbeidh do shocrú féin i bhfeidhm.',
  'De paginamaat en marges komen nu uit je instellingen, dus bij een ander kan het document anders uitvallen. Zet ze in het document om dat vast te leggen.':
      'Tagann méid an leathanaigh agus na himill ó do chuid socruithe anois, agus mar sin d\'fhéadfadh an cháipéis breathnú difriúil ag duine eile. Stóráil sa cháipéis iad chun iad a shocrú.',
