  'Kolom weghalen': 'Scrios an colún',
  'Met afloop wordt de pagina rondom groter dan het gekozen formaat, zodat inkt die tot de rand loopt dóór de snijlijn heen gaat. De afloop geldt voor élke export tot je hem weer op 0 zet. Laat dit op 0 voor gewoon afdrukken.':
      'Le fuiliú bíonn an leathanach níos mó ná an mhéid roghnaithe ar gach taobh, sa chaoi is go leanann dúch a shroicheann an t-imeall thar líne an bhearrtha. Baineann an fuiliú le gach easpórtáil go dtí go gcuireann tú ar ais go 0 é. Fág ar 0 é le haghaidh gnáthphriontála.',
