  'Kies naar welke dia de presentatie na deze springt. Standaard is dat gewoon de volgende dia. Zo laat je een keuze-tak aan het eind terugkeren naar het menu.':
      'Roghnaigh cén sleamhnán a léimeann an cur i láthair chuige tar éis an cheann seo. De réir réamhshocraithe is é sin an chéad sleamhnán eile go simplí. Mar sin is féidir le brainse rogha filleadh ar an roghchlár ag an deireadh.',
  'De doeldia bestaat niet meer — de presentatie gaat hier gewoon verder.':
      'Níl an sprioc-sleamhnán ann a thuilleadh — leanann an cur i láthair ar aghaidh anseo go simplí.',
  'Bewerk deze dia als markdown-bron':
      'Cuir an sleamhnán seo in eagar mar fhoinse markdown',
  'Dit is een presentatie, geen Markdown-bestand. OciDeck kan hem importeren naar een nieuw deck.':
      'Is cur i láthair é seo, ní comhad Markdown é. Is féidir le OciDeck é a iompórtáil isteach i ndeic nua.',
  'Dit is een presentatie, geen Markdown-bestand. Zet de module Importeren aan om hem om te zetten naar een deck.':
      'Is cur i láthair é seo, ní comhad Markdown é. Cuir an modúl Iompórtáil ar siúl chun é a thiontú ina dheic.',
  'De zwakhedenlijst (78): id, titel, MASVS-categorie, platform, de CWE-koppeling en een korte omschrijving. Plus een brug van de oude beta-nummering (tot 0119) naar de canonieke id\'s, zodat de MASTG-kruiskoppeling blijft kloppen.':
      'Liosta na laigí (78): id, teideal, catagóir MASVS, ardán, an nasc CWE agus cur síos gairid. Chomh maith le sin, droichead ón sean-uimhriú béite (suas go 0119) go dtí na id canónacha, ionas go bhfanfaidh an chrostagairt MASTG ceart.',
  'Alle integraties': 'Gach comhtháthú',
  'Alles inschakelen': 'Cumasaigh gach ceann',
  'Alles uitschakelen': 'Díchumasaigh gach ceann',
  'Koppelingen met andere systemen. Elke koppeling staat standaard uit en blijft inactief tot u haar inschakelt.':
      'Naisc le córais eile. Tá gach nasc múchta de réir réamhshocraithe agus fanann sé neamhghníomhach go dtí go gcumasaíonn tú é.',
  'Presentaties uit PowerPoint (.pptx), Keynote (.key) en Impress (.odp) binnenhalen als bewerkbaar deck. Koppelingen met andere systemen, zoals OpenKAT, staan onder Integraties.':
      'Láithreoireachtaí a thabhairt isteach ó PowerPoint (.pptx), Keynote (.key) agus Impress (.odp) mar deck ineagarthóireachta. Tá naisc le córais eile, ar nós OpenKAT, faoi Chomhtháthuithe.',
