  '{bestand} is groter dan de limiet van {limiet} en wordt niet geïmporteerd.':
      'Tá {bestand} níos mó ná an teorainn {limiet} agus ní dhéanfar é a iompórtáil.',
  '{bestand} is geen herkende presentatie. OciDeck leest PowerPoint (.pptx), OpenDocument (.odp) en Keynote (.key).':
      'Ní cur i láthair aitheanta é {bestand}. Léann OciDeck PowerPoint (.pptx), OpenDocument (.odp) agus Keynote (.key).',
  '{bestand} lijkt beschadigd: het archief kan niet volledig worden uitgepakt.':
      'Dealraíonn sé go bhfuil {bestand} damáiste: ní féidir an chartlann a bhaint amach go hiomlán.',
  'Het {formaat}-formaat wordt nog niet ondersteund ({bestand}).':
      'Níl tacaíocht ann fós don fhormáid {formaat} ({bestand}).',
  'Geen dia’s gevonden in {bestand} — is dit een geldig {formaat}-bestand?':
      'Níor aimsíodh aon sleamhnán in {bestand} — an comhad {formaat} bailí é seo?',
  'Kon {bestand} niet lezen als {formaat}-presentatie.':
      'Níorbh fhéidir {bestand} a léamh mar chur i láthair {formaat}.',
  'Wat doen we met deze dia’s?': 'Cad a dhéanfaimid leis na sleamhnáin seo?',
  'Deze dia’s konden niet volledig worden omgezet. Kies per dia wat er moet gebeuren; wat u niet aanraakt wordt zo volledig mogelijk overgenomen, met een notitie erbij over wat er ontbreekt.':
      'Níorbh fhéidir na sleamhnáin seo a thiontú go hiomlán. Roghnaigh do gach sleamhnán cad ba cheart a dhéanamh; rud ar bith nach mbaineann tú leis, tógfar chomh hiomlán agus is féidir é, le nóta faoina bhfuil ar iarraidh.',
  'Voor alle dia’s:': 'Do gach sleamhnán:',
  'Dia': 'Sleamhnán',
  'Zo volledig mogelijk': 'Chomh hiomlán agus is féidir',
  'Alleen de afbeelding': 'An íomhá amháin',
  'Import afbreken': 'Cealaigh an iompórtáil',
  'Niet meer vragen': 'Ná fiafraigh arís',
  'Voortaan alles zo volledig mogelijk overnemen.':
      'As seo amach, tógtar gach rud chomh hiomlán agus is féidir.',
  'De checklist-index: per test het stabiele id, de canonieke titel en de categorie. De inhoud van de gids zelf is niet gebundeld.':
      'Innéacs an tseicliosta: in aghaidh gach tástála, an t-aitheantóir seasmhach, an teideal canónta agus an chatagóir. Níl ábhar an treoraí féin faoi iamh.',
  'De test-index van v2.0.0: per test het stabiele id, de canonieke titel, de MASVS-categorie en de MASWE-zwakheid. De ingetrokken v1-tests en de placeholders zitten er niet in; de inhoud van de gids evenmin.':
      'Innéacs tástálacha v2.0.0: in aghaidh gach tástála, an t-aitheantóir seasmhach, an teideal canónta, an chatagóir MASVS agus an laige MASWE. Níl tástálacha v1 a tarraingíodh siar ná ionadchoinneálaithe san áireamh; ná ábhar an treoraí ach oiread.',
  'De volledige lijst (id, naam, beschrijving) plus een eigen geselecteerde kern met onze remediatie-notities.':
      'An liosta iomlán (aitheantóir, ainm, cur síos) chomh maith le croí roghnaithe dár gcuid féin le nótaí leigheasta.',
  'Het volledige EIS-schema (88 toetsbare eisen).':
      'An scéimre EIS iomlán (88 riachtanas intástála).',
  'Aandoeningsnamen in negen talen als gezondheidslexicon voor de privacycontrole (assets/privacy/health_lexicon.json).':
      'Ainmneacha riochtaí i naoi dteanga mar fhoclóir sláinte don seiceáil príobháideachais (assets/privacy/health_lexicon.json).',
  'Een eigen Dart-implementatie van de publieke specificatie, inclusief de MacroVector-tabel en de gepubliceerde bandindeling.':
      'Ár bhfeidhmiú Dart féin ar an tsonraíocht phoiblí, lena n-áirítear an tábla MacroVector agus na bandaí déine foilsithe.',
  'Specificatie van FIRST.Org — attributie':
      'Sonraíocht FIRST.Org — aitreabúid',
