  'Toon hoeveel items verborgen zijn': 'Taispeáin cé mhéad mír atá folaithe',
  'Toon alleen een deel van de bullets, tabel of grafiek. De oorspronkelijke data blijft in het bestand bewaard.':
      'Ná taispeáin ach cuid de na hurchair, den tábla nó den chairt. Fanann na sonraí bunaidh sábháilte sa chomhad.',
  'Voor tabellen: kolomindex of naam om op te sorteren. Voor grafieken: naam van de reeks.':
      'Do tháblaí: innéacs nó ainm an cholúin le sórtáil. Do chairteacha: ainm na sraithe.',
  'Online opslag is alleen beschikbaar in de desktopversie.':
      'Níl stóráil ar líne ar fáil ach sa leagan deisce.',
  'Online opslag': 'Stóráil ar líne',
  'Presentaties openen uit en opslaan naar WebDAV, S3 en git-repository’s, met versiebeheer en samenwerken via een forge. Een deel van deze paden is tot nu toe vooral tegen testomgevingen beproefd; kies dit bewust. Zonder de module werkt alles lokaal gewoon: mappen, bestanden en pakketten.':
      'Oscail cur i láthair ó WebDAV, S3 agus stórais git agus sábháil chucu iad, le rialú leaganacha agus comhoibriú trí forge. Go dtí seo is in aghaidh timpeallachtaí tástála is mó a triaileadh cuid de na cosáin seo; roghnaigh é seo go comhfhiosach. Gan an modúl oibríonn gach rud áitiúil mar is gnách: fillteáin, comhaid agus pacáistí.',
  'Er staan al online verbindingen ingesteld; die blijven werken, net als wachtend werk in de wachtrij. Uit betekent alleen: geen nieuwe online verbindingen toevoegen.':
      'Tá naisc ar líne socraithe cheana féin; leanann siad ag obair, mar aon leis an obair atá ag fanacht sa scuaine. Ní chiallaíonn múchta ach: gan naisc nua ar líne a chur leis.',
  'De module AI-assistentie staat uit, dus hier gebeurt niets. Zet hem aan bij Uitbreidingen. Wat je hieronder hebt ingesteld blijft staan.':
      'Tá an modúl Cúnamh II múchta, mar sin ní tharlaíonn aon rud anseo. Cuir ar siúl é faoi Breiseáin. Fanann a bhfuil socraithe agat thíos mar atá.',
  'Hulp bij alt-teksten, beschrijvingen en formuleringen. Aanzetten verstuurt nog niets: dat gebeurt pas nadat je zelf een backend hebt gekozen en, bij een clouddienst, uitdrukkelijk hebt bevestigd. Een lokale backend verlaat je computer niet.':
      'Cabhair le téacsanna malartacha, cur síos agus friotal. Ní sheolann é a chur ar siúl aon rud go fóill: ní tharlaíonn sé sin ach amháin tar éis duit inneall a roghnú tú féin agus, i gcás seirbhís néil, é a dheimhniú go sainráite. Le hinneall áitiúil ní fhágann aon rud do ríomhaire.',
  'Kies de backend op het tabblad AI-assistentie. Zolang daar niets staat, gebeurt er niets.':
      'Roghnaigh an t-inneall ar an táb Cúnamh II. Fad is nach bhfuil aon rud socraithe ansin, ní tharlaíonn aon rud.',
  'De voorbeelddia\'s van een sjabloon staan in het Engels. Naam en omschrijving volgen je eigen taal; de inhoud pas je na het aanmaken aan.':
      'Tá sleamhnáin shamplacha teimpléid i mBéarla. Leanann an t-ainm agus an cur síos do theanga féin; cuireann tú an t-ábhar in oiriúint tar éis é a chruthú.',
  'Meer': 'Tuilleadh',
  'Leesbaarheid van dit profiel': 'Inléiteacht na próifíle seo',
  'Alle onderdelen halen de norm.': 'Comhlíonann gach cuid an caighdeán.',
  'Deze verhoudingen gaan over de app zelf, niet over je dia\'s.':
      'Baineann na cóimheasa seo leis an aip féin, ní le do shleamhnáin.',
  'Tekst op kaarten en dialogen': 'Téacs ar chártaí agus ar dhialóga',
  'Tekst op de schermachtergrond': 'Téacs ar chúlra an scáileáin',
  'Tekst en pictogrammen in de zijbalk':
      'Téacs agus deilbhíní sa bharra taoibh',
  'Titel in de bovenbalk': 'Teideal sa bharra uachtarach',
  'Tekstknoppen en links': 'Cnaipí téacs agus naisc',
  'Selectievakjes, schakelaars en de tekstcursor':
      'Ticbhoscaí, lasca agus an cúrsóir téacs',
  'Het vinkje in een aangevinkt vakje': 'An tic i mbosca ticeáilte',
  'Label op de primaire knop': 'Lipéad ar an bpríomhchnaipe',
  'Bevindingen die je hebt beoordeeld en hebt laten staan. Ze worden niet meer gemeld, maar de scan blijft ze vinden en ze tellen niet als opgelost. Tik om er een terug te zetten.':
      'Fionnachtana a ndearna tú athbhreithniú orthu agus a d\'fhág tú mar atá. Ní thuairiscítear a thuilleadh iad, ach aimsíonn an scanadh fós iad agus ní áirítear réitithe iad. Tapáil chun ceann a chur ar ais.',
  'Deze is beoordeeld en mag blijven': 'Seiceáilte, féadann sé seo fanacht',
  'Mogelijk gemaakt door': 'Arna chumasú ag',
  'De export is gestopt tijdens het voorbereiden.':
      'Stop an t-easpórtáil le linn an ullmhúcháin.',
  'Het bestand kon niet worden opgebouwd of weggeschreven. Controleer of er schijfruimte is en of de exportmap beschrijfbaar is.':
      'Níorbh fhéidir an comhad a thógáil ná a scríobh. Deimhnigh go bhfuil spás diosca ann agus gur féidir scríobh chuig an bhfillteán easpórtála.',
  'Het renderen van de dia\'s naar beeld is mislukt. Dit ligt aan een dia, niet aan het bestandsformaat: de HTML-export komt hier niet langs en werkt in dit geval meestal wel.':
      'Theip ar rindreáil na sleamhnán ina n-íomhánna. Sleamhnán is cúis leis, ní hé formáid an chomhaid: ní théann an t-easpórtáil HTML an bealach seo agus oibríonn sé de ghnáth sa chás seo.',
  'Technische melding:': 'Teachtaireacht theicniúil:',
  'presentaties': 'laithreoidi',
  '/Presentaties': '/Láithreoidí',
  'De export is mislukt.': 'Theip ar an easpórtáil.',
  'Presenteer vanaf hier': 'Cuir i láthair ón áit seo',
  'Traffic Light Protocol: hoe breed mag dit materiaal gedeeld worden?':
      'Traffic Light Protocol: cé chomh forleathan is féidir an t-ábhar seo a roinnt?',
  'Wat betekenen deze niveaus?': 'Cad is brí leis na leibhéil seo?',
  'het classificatiebeleid bewaakt wat er uit mag.':
      'coinníonn an polasaí aicmithe súil ar a bhfuil cead imeacht.',
  'de markering reist mee, maar er is geen drempel: zet het classificatiebeleid aan onder Instellingen → Algemeen.':
      'taistealaíonn an marc leis, ach níl aon bhac ann: cuir an polasaí aicmithe ar siúl faoi Socruithe → Ginearálta.',
  'Dit document bestaat alleen in het Engels.':
      'Níl an cháipéis seo ar fáil ach i mBéarla.',
  'Dit bestand bestaat niet meer op deze plek.':
      'Níl an comhad seo san áit seo a thuilleadh.',
  'Dit bestand is te groot om te openen.':
      'Tá an comhad seo rómhór le hoscailt.',
  'Deze presentatie is beschadigd of half opgeslagen.':
      'Tá an láithreoireacht seo damáiste nó níor sábháladh í ach go páirteach.',
  'Dit bestand is geen leesbare tekst. OciDeck opent Markdown.':
      'Ní téacs inléite é an comhad seo. Osclaíonn OciDeck Markdown.',
  'Deze dia is leeg: hij toont niets op het scherm en in de export.':
      'Tá an sleamhnán seo folamh: ní thaispeánann sé aon rud ar an scáileán ná san easpórtáil.',
  'Export geblokkeerd door classificatiebeleid: stel een TLP-niveau in voor deze presentatie.':
      'Easpórtáil bactha ag an mbeartas aicmithe: socraigh leibhéal TLP don láithreoireacht seo.',
  'Export geblokkeerd door classificatiebeleid: dit deck is {deck}, lager dan het vereiste minimum {limit}.':
      'Easpórtáil bactha ag an mbeartas aicmithe: tá an láithreoireacht seo {deck}, faoi bhun an íosmhéid riachtanaigh {limit}.',
  'Export geblokkeerd door classificatiebeleid: dit deck is {deck}, hoger dan het toegestane vrijgaveniveau {limit}.':
      'Easpórtáil bactha ag an mbeartas aicmithe: tá an láithreoireacht seo {deck}, os cionn na huasteorann scaoilte ceadaithe {limit}.',
  'niet geclassificeerd': 'gan aicmiú',
  'Regels die nu uit staan. Deze worden niet gemeld en niet geredigeerd. Drie ervan staan standaard uit — hun trefwoorden komen op gewone zakelijke slides te vaak voor. Tik om er een aan te zetten.':
      'Rialacha atá múchta faoi láthair. Ní thuairiscítear iad agus ní fholaítear iad. Tá trí cinn díobh múchta de réir réamhshocraithe — bíonn a n-eochairfhocail le feiceáil rómhinic ar ghnáthshleamhnáin oibre. Tapáil chun ceann a chur ar siúl.',
  'Bekende beperkingen': 'Teorainneacha aitheanta',
  'naam@example.org\nexample.org': 'ainm@example.org\nexample.org',
  'Een laag naast dit deck was te groot en is niet ingelezen; het bestand zelf is ongewijzigd:':
      'Bhí sraith in aice leis an deic seo rómhór agus níor lódáladh í; níl aon athrú ar an gcomhad féin:',
  'Deze tijdstempel hoort niet bij het laatste verzoek':
      'Ní bhaineann an stampa ama seo leis an iarratas is déanaí',
  'Vermeld dit versienummer wanneer u een beveiligingsprobleem meldt.':
      'Luaigh an uimhir leagain seo nuair a thuairiscíonn tú fadhb slándála.',
