      'Camóg-scartha, m.sh. OWASP WSTG@4.2',
  'Titel van de presentatie': 'Teideal an chur i láthair',
  'F-03 · SQL-injectie in het loginformulier':
      'F-03 · Instealladh SQL san fhoirm logála isteach',
  'https://app.voorbeeld/login': 'https://app.example/login',
  'Deze afbeelding naar het AI-model sturen?':
      'An íomhá seo a sheoladh chuig an tsamhail II?',
  'De afbeelding gaat ongewijzigd naar': 'Seolfar an íomhá gan athrú chuig',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'Ní fholaíonn OciDeck aon rud laistigh d\'íomhá: seoltar aghaidheanna, téacs ar ghabháil scáileáin agus sonraí atá le feiceáil leis.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Fuair an tseiceáil íomhánna aghaidh inaitheanta amháin nó níos mó anseo.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Cruthaítear dhá chomhad in aice leis an easpórtáil, ionas gur féidir leis an bhfaighteoir na foluithe a sheiceáil.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'liostaíonn sé a bhfuil fágtha ar lár, gan na luachanna féin. Is féidir an comhad seo a chur leis an tuairisc.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'tá na heochracha ann lenar féidir gach luach folaithe a ríomh ar ais. Ná seol an comhad seo leis: cuirtear an folú ar ceal ansin. Coinnigh in aice leis an bhfoinse é.',
  'slides': 'sleamhnáin',
  'Achtergehouden': 'Coinnithe siar',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Coinnithe siar: aicmithe níos déine ná an cur i láthair',
  '1 slide achtergehouden door haar TLP': '1 sleamhnán coinnithe siar ag a TLP',
  'slides achtergehouden door hun TLP': 'sleamhnáin coinnithe siar ag a TLP',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Fágtar na sleamhnáin seo ar lár agus tú ag cur i láthair, ag easpórtáil nó sa phacáiste. Ardaigh leibhéal TLP an chur i láthair in Eolas an chur i láthair chun iad a chur san áireamh.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Coinnítear gach sleamhnán siar de bharr a n-aicmithe TLP — níl aon rud le taispeáint.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Coinnítear gach sleamhnán siar de bharr a n-aicmithe TLP — níl aon rud le heaspórtáil.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Ligeadh thar bráid gach sleamhnán nó coinníodh siar é de bharr a aicmithe TLP — níl aon rud le taispeáint.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Ligeadh thar bráid gach sleamhnán nó coinníodh siar é de bharr a aicmithe TLP — níl aon rud le heaspórtáil.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Níor sábháladh figiúirí na gcairteacha — níl siad ann a thuilleadh ach san fhuinneog seo:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Sa bhrabhsálaí níl aon aisghabháil tar éis tuairte: má dhúnann tú an cluaisín seo, imíonn obair nár sábháladh. Sábháil do chur i láthair tú féin.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  An bunachar sonraí CVE áitiúil (tusa a chuireann an íoslódáil ar bun): faigheann OciDeck na sonraí ollmhóra trí api.github.com agus an comhad eisiúna a bhfuil an seoladh sin ag díriú air.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Cuardach CVE (múchta de réir réamhshocraithe): nuair atá sé lasta, téann do théarma cuardaigh chuig an scáthán CVE atá socraithe agus, mura bhfaigheann sin aon rud, chuig bunachar sonraí Eorpach ENISA agus chuig MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Luchtaíonn físeán YouTube nó Vimeo leabaithe an seinnteoir ón tseirbhís sin.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Sa bhrabhsálaí: má dhiúltaíonn an brabhsálaí seoladh a fháil go díreach, déanann OciDeck iarracht eile tríd an bhfreastalaí ar tháinig an feidhmchlár uaidh; sroicheann an seoladh sin an freastalaí sin ansin.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Níor sábháladh an cúlghairm. Ag an gcéad tosú eile, beidh do thoiliú i bhfeidhm arís.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Ceannteideal rannóige a fhógraíonn cuid nua den chur i láthair. Coinnigh gearr é. Cuir íomhá chúlra leis ón leabharlann íomhánna.',
  'Bronnen doorzoeken…': 'Ag cuardach foinsí…',
  'Niet doorzocht': 'Gan chuardach',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Ní ritheann an tseiceáil seo sa leagan gréasáin: teastaíonn leabharlann córais ón mbrath aghaidhe nach bhfuil ag an mbrabhsálaí. Bain úsáid as an leagan deisce chun aghaidheanna in íomhánna a sheiceáil.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Teastaíonn rochtain léimh agus scríofa ar an stór ón gcomhartha. Níl cuardach ar an bhfreastalaí ag Gitea ná Forgejo; déanann OciDeck cuardach go háitiúil.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Teastaíonn an scóip repo ón gcomhartha (nó mionsonraithe: Contents léamh agus scríobh).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Teastaíonn read_repository, write_repository agus read_api ón gcomhartha. Teastaíonn Advanced nó Exact Search do chuardach ar an bhfreastalaí.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Cuardach tapa ar an bhfreastalaí — mar gheall ar mhoill innéacsúcháin, d\'fhéadfadh deic a athraíodh le déanaí a bheith ar iarraidh.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Ní choimeádtar na meáin i ngnáthchomhad .md',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Ní mhaireann na híomhánna, an físeán agus an fhuaim a roghnaigh tú sa chluaisín seo ach sa chuimhne. Ní choimeádann gnáthchomhad .md iad — bíonn siad imithe nuair a osclaíonn tú arís é. Easpórtáil mar phacáiste .ocideck chun na meáin a thabhairt leat.',
  'Media verwijderd om privacyredenen':
      'Baineadh na meáin as ar chúiseanna príobháideachais',
  'Afbeeldingen door AI laten taggen?':
      'Lig don IS na híomhánna seo a chlibeáil?',
