  'Lager is beter': 'Is fearr níos ísle',
  'Hoger is beter': 'Is fearr níos airde',
  'Neutraal': 'Neodrach',
  'Nu': 'Anois',
  'Vorige rapportage': 'An tuairisc roimhe seo',
  'Een scorecard toont hoogstens vijf cijfers; meer leest niet meer als een oordeel.':
      'Taispeánann cárta scóir cúig fhigiúr ar a mhéad; níos mó ná sin, ní léitear é mar bhreithiúnas.',
  'Laat de vorige rapportage leeg als er nog geen meting was; de slide toont dan geen verandering.':
      'Fág an tuairisc roimhe seo folamh mura raibh tomhas ann fós; ní thaispeánfaidh an sleamhnán athrú ansin.',
  'Bepaalt of een stijging groen of rood kleurt. De pijl volgt altijd de cijfers.':
      'Cinneann sé an mbeidh ardú glas nó dearg. Leanann an tsaighead na figiúirí i gcónaí.',
  'Een paar kerncijfers met het cijfer van de vorige rapportage ernaast, zodat de verandering het verhaal vertelt. Geef per cijfer aan of stijgen goed of slecht nieuws is.':
      'Cúpla príomhfhigiúr le figiúr na tuairisce roimhe seo lena dtaobh, ionas gurb é an t-athrú a insíonn an scéal. Luaigh do gach ceann acu an dea-scéal nó drochscéal é ardú.',
  'Zekere vondsten als fout behandelen':
      'Caith le fionnachtana cinnte mar earráidí',
  'Normaal is een zekere vondst — een BSN, een IBAN, een e-mailadres — een waarschuwing die je kunt negeren. Aan maakt er een fout van, en dan kan de export erop blokkeren als je die instelling ook aan hebt staan. Bedoeld voor omgevingen waar zulke gegevens er echt niet doorheen mogen. Onzekere vondsten blijven een waarschuwing.':
      'De ghnáth is rabhadh é fionnachtain chinnte — uimhir aitheantais, IBAN, seoladh ríomhphoist — ar féidir leat neamhaird a dhéanamh air. Déanann sé earráid de nuair atá sé ann, agus ansin is féidir leis an easpórtáil bac a chur air má tá an socrú sin agat ar siúl freisin. Ceaptha do thimpeallachtaí nach mór do shonraí den sórt sin gan dul tríd i ndáiríre. Fanann fionnachtana neamhchinnte ina rabhadh.',
  'Medicare-nummer — een zorggegeven': 'uimhir Medicare — sonra sláinte',
  'bedrijfsnummer': 'uimhir chuideachta',
  'zorgverzekeringsnummer (RAMQ) — een zorggegeven':
      'uimhir árachais sláinte (RAMQ) — sonra sláinte',
  'zorgverzekeringsnummer (OHIP) — een zorggegeven':
      'uimhir árachais sláinte (OHIP) — sonra sláinte',
  'bedrijfsnummer (BN)': 'uimhir ghnó (BN)',
  'zorgverlenersnummer (NPI)': 'uimhir sholáthraí cúraim sláinte (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'uimhir Medicare (MBI) — sonra sláinte',
  'wacht op verbinding': 'ag fanacht le nasc',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Sábháilte ar an ríomhaire seo, níl sé sa stór fós. Rachaidh sé leis a luaithe a bheidh nasc ann arís — nó anois, le "Folmhaigh an scuaine".',
  'Branch (optioneel)': 'Brainse (roghnach)',
  'let op: de standaardbranch is':
      'tabhair faoi deara: is é an brainse réamhshocraithe',
  'jij werkt op': 'tá tú ag obair ar',
  'werkgeversnummer (EIN)': 'uimhir fostóra (EIN)',
  'laatste vier cijfers van een SSN': 'ceithre dhigit dheireanacha SSN',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'dáta breithe, cód poist agus inscne le chéile — is gnách go gcuireann an triúr sin duine amháin in iúl, fiú gan ainm',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Níl muinín as teastas an fhreastalaí seo. Ar fhreastalaí féin-óstáilte is féidir leat féachaint air agus muinín a chur ann faoi Socruithe → Stóráil.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Níl muinín as teastas an forge seo. Ar forge féin-óstáilte is féidir leat féachaint air agus muinín a chur ann faoi Socruithe → Stóráil.',
  'Het certificaat van het endpoint wordt niet vertrouwd. Bij een zelf gehost endpoint kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Níl muinín as teastas an endpoint seo. Ar endpoint féin-óstáilte is féidir leat féachaint air agus muinín a chur ann faoi Socruithe → Stóráil.',
  'Het certificaat van de forge wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Níl muinín as teastas an forge — féinsínithe, as feidhm, nó eisithe chuig ainm eile.',
  'Het certificaat van het endpoint wordt niet vertrouwd — zelfondertekend, verlopen, of op een andere naam gesteld.':
      'Níl muinín as teastas an endpoint — féinsínithe, as feidhm, nó eisithe chuig ainm eile.',
  'creditcardnummer': 'uimhir chárta creidmheasa',
  'beveiligingscode van een creditcard': 'cód slándála cárta (CVV)',
  'gegevens in de sprekersnotities — onzichtbaar op de slide, wél in de export':
      'sonraí i nótaí an chainteora — dofheicthe ar an sleamhnán, ach easpórtáiltear iad',
  'Certificaat vertrouwen?': 'Muinín as an teastas seo?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'Níl teastas an fhreastalaí seo sínithe ag eisitheoir aitheanta. Tá sin gnách i gcás freastalaí féin-óstáilte, ach sin an chuma a bhíonn ar nasc idircheaptha freisin.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Cuir an mhéarlorg thíos i gcomparáid leis an gceann a thaispeánann do fhreastalaí féin. Má tá siad mar an gcéanna, tá tú ag caint leis an meaisín ceart.',
  'Uitgegeven aan': 'Eisithe chuig',
  'Uitgegeven door': 'Eisithe ag',
  'Geldig tot': 'Bailí go dtí',
  'Vingerafdruk (SHA-256)': 'Méarlorg (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Ní chuirtear muinín ach sa teastas seo amháin. Má chuireann an freastalaí ceann eile ina áit, fiafróidh OciDeck arís.',
  'Vertrouwen': 'Muinín',
  'Certificaat bekijken': 'Féach ar an teastas',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Na háiteanna ina gcoinníonn tú agus ina gcuardaíonn tú do chuid cur i láthair — fillteáin ar an ríomhaire seo, freastalaithe WebDAV, buicéid S3 agus stórais git measctha. Tarraing iad san ord is mian leat: an ceann is airde de chineál, is é an réamhshocrú é.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Stóráil S3: nuair a cheanglaíonn tú le buicéad, coinnítear an críochphointe, ainm an bhuicéid agus d\'eochair rochtana (an eochair rúnda go sábháilte in eochairslabhra do chórais) agus seoltar na cur i láthair a osclaíonn nó a shábhálann tú chuig an tseirbhís stórála sin.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Stóráil Git: nuair a cheanglaíonn tú le stór, coinnítear do chomhartha rochtana (go sábháilte in eochairslabhra do chórais) agus seoltar na cur i láthair a shábhálann tú chuig an bhfreastalaí sin mar commits. Fanann cóip oibre den stór gan chriptiú ar an ngléas seo.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Tá ainmneacha galar in easnamh do theanga an deic seo. Aithnítear reiligiún, tuairim pholaitiúil agus téarmaí ceardchumainn, agus oibríonn patrúin le digit seiceála (PPS, IBAN, pas) i gcónaí — ach ná bí ag brath ar dhiagnóis a aimsiú.',
  'niet getest': 'gan tástáil',
  'Werkte op': 'D\'oibrigh sé ar',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Tá tú sínithe isteach, ach níl rochtain agat anseo. Ní hé do phasfhocal an fhadhb — iarr cearta ar an riarthóir don fhillteán seo.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'Tá do chomhartha bailí, ach níl cead aige é seo a dhéanamh. Tabhair níos mó cearta dó, nó fan má tá teorainn á cur i bhfeidhm ag an forge.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'Tá an comhartha bailí, ach níl cead aige é seo a dhéanamh — tabhair níos mó cearta dó ar an stór.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Sínithe isteach, ach gan rochtain — ní hé do phasfhocal an fhadhb. Iarr cearta don fhillteán seo.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Tá cuma URL DAV iomlán air seo. I gcás Nextcloud, díorthaíonn OciDeck an chonair sin é féin — níl anseo ach an freastalaí.',
  'Overnemen': 'Cuir i bhfeidhm',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'Níl WebDAV socraithe i gceart — seiceáil sonraí an fhreastalaí faoi Socruithe → Stóráil.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'Níl an stór git socraithe i gceart — seiceáil freastalaí, úinéir agus stór faoi Socruithe → Stóráil.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'Níl ainm fhreastalaí an forge ann, nó ní féidir é a chuardach. Seiceáil URL an fhreastalaí le haghaidh botúin chlóscríofa.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Tá seoladh príobháideach nó LAN ag an forge seo. Marcáil é mar inmheánach iontaofa faoi Socruithe → Stóráil.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'Níl teacht ar an forge — seiceáil do nasc agus URL an fhreastalaí.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'Theip ar an síniú isteach chuig an forge. Seiceáil do chomhartha: teastaíonn rochtain léitheoireachta ar an stór uaidh, agus rochtain scríofa chun sábháil.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Níor aimsíodh sa stór é — nó b\'fhéidir nach bhfuil cead ag do chomhartha é a fheiceáil.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'Sheol an forge earráid ar ais. Bain triail eile as níos déanaí.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Ní fhreagraíonn an seoladh seo mar forge. An bhfuil an cineál forge faoi Socruithe → Stóráil ceart?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Socraigh freastalaí WebDAV ar dtús faoi Socruithe → Stóráil.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Ag teastáil nuair a ritheann an forge ar líonra príobháideach nó baile. Gan an bhratach seo diúltaíonn an tseiceáil slándála seoladh príobháideach.',
  'Vul server-URL, eigenaar en repository in':
      'Líon isteach URL an fhreastalaí, an t-úinéir agus an stór',
  'de standaardbranch heet': 'tugtar ar an mbrainse réamhshocraithe',
  'die wordt voortaan gebruikt': 'úsáidfear é sin as seo amach',
  'de repository is nog leeg; de eerste opslag vult hem':
      'tá an stór folamh fós; líonfaidh an chéad sábháil é',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'tabhair faoi deara: ní féidir leis an gcomhartha seo ach léamh, mar sin teipfidh ar an sábháil',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'Theip ar an síniú isteach — seiceáil an comhartha. Teastaíonn rochtain léitheoireachta ar an stór uaidh, agus rochtain scríofa chun sábháil.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Níor aimsíodh an stór — nó b\'fhéidir nach bhfuil cead ag do chomhartha é a fheiceáil. Seiceáil an t-úinéir agus ainm an stóir.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Ní fhreagraíonn an seoladh seo mar forge. An bhfuil an cineál forge a roghnaigh tú ceart?',
  'kenteken': 'uimhir chláraithe feithicle',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Níl liosta eochairfhocal ann do chatagóirí speisialta sonraí pearsanta i dteanga an deic seo. Oibríonn patrúin le digit seiceála (PPS, IBAN, pas); ní aithnítear focail ar nós "diagnóis" nó "duine faoi amhras".',
  'Landpakketten voor identificatienummers':
      'Pacáistí tíre d\'uimhreacha aitheantais',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Tá uimhreacha ar nós BSN na hÍsiltíre nó PESEL na Polainne sainiúil do thír. Tá an Eoraip ar fad ann mar go bhfuil digit seiceála ag formhór na n-uimhreacha sin: ní chosnaíonn iad a chur ar siúl beagnach aon fholáireamh bréagach. Tá IBAN, ríomhphost, rúin agus stiallacha pas neamhspleách air seo agus seiceáiltear i gcónaí iad.',
  'strafrechtelijk gegeven (verdachte)': 'sonraí coiriúla (duine faoi amhras)',
  'strafrechtelijk gegeven (aangever of slachtoffer)':
      'sonraí coiriúla (gearánach nó íospartach)',
