  'Controleer de internetverbinding en probeer opnieuw.':
      'Seiceáil an nasc idirlín agus bain triail eile as.',
  'Privacy blokkeert export':
      'Cuireann an phríobháideacht bac ar an easpórtáil',
  'privacybevinding(en) zonder keuze':
      'toradh/torthaí príobháideachais gan rogha',
  'Persoonsgegevens, bijzondere gegevens en geheimen in de tekst':
      'Sonraí pearsanta, sonraí speisialta agus rúin sa téacs',
  'Slides, notities, tabellen, code, bestandspaden en URL\'s worden op dit apparaat doorzocht op identificerende nummers, financiële gegevens, contactgegevens, digitale identificatoren, geheimen, bijzondere persoonsgegevens (AVG art. 9/10), massagegevens en metadatalekken.':
      'Cuardaítear sleamhnáin, nótaí, táblaí, cód, conairí comhad agus URLanna ar an ngléas seo le haghaidh uimhreacha aitheantais, sonraí airgeadais, sonraí teagmhála, aitheantóirí digiteacha, rún, catagóirí speisialta sonraí pearsanta (RGCS airt. 9/10), sonraí ollmhóra agus sceitheadh meiteashonraí.',
  'Alleen een zekere treffer waarschuwt; waarschijnlijk en mogelijk blijven informatief. Een uitgezette regel vuurt nergens.':
      'Ní thugann ach toradh cinnte rabhadh; fanann dóchúil agus féideartha faisnéiseach. Ní lasann riail dhíchumasaithe áit ar bith.',
  'Niet gecontroleerd: persoonsgegevens, bijzondere gegevens en geheimen. De privacycontrole staat uit bij Beveiliging.':
      'Gan seiceáil: sonraí pearsanta, sonraí speisialta agus rúin. Tá an tseiceáil príobháideachais múchta faoi Slándáil.',
  'Op deze slide': 'Ar an sleamhnán seo',
  'Tijdens presenteren': 'Le linn cur i láthair',
  'Classificatie en privacy': 'Aicmiú agus príobháideachas',
  'Logo tonen': 'Taispeáin lógó',
  'Footer tonen': 'Taispeáin buntásc',
  'Tabel bewerkbaar': 'Tábla ineagarthóireachta',
  'Laat je de tabel tijdens het presenteren voor de zaal aanpassen. Staat standaard uit.':
      'Ligeann duit an tábla a athrú os comhair an lucht féachana le linn cur i láthair. As de réir réamhshocraithe.',
  'Automatisch doorgaan': 'Téigh ar aghaidh go huathoibríoch',
  'Persoonsgegevens': 'Sonraí pearsanta',
  'Wijzigen': 'Athraigh',
  'Automatisch afspelen': 'Seinn go huathoibríoch',
  'Melden': 'Tuairiscigh',
  'Geaccepteerd': 'Glactha',
  'Gewaarschuwd': 'Rabhadh tugtha',
  'Weggelaten': 'Fágtha ar lár',
  'Bewerkbaar': 'Ineagarthóireachta',
  'De privacycontrole': 'An tseiceáil príobháideachais',
  'OciDeck leest je dia\'s na op gegevens die privacygevoelig kunnen zijn: identificatienummers, contactgegevens, telefoonnummers, bankrekeningen, sleutels en wachtwoorden, en bijzondere persoonsgegevens. Dat gebeurt volledig op dit apparaat: er wordt niets verstuurd, en de gevonden waarde zelf komt in geen enkele melding te staan.':
      'Léann OciDeck do shleamhnáin le haghaidh sonraí a d\'fhéadfadh a bheith íogair ó thaobh príobháideachais de: uimhreacha aitheantais, sonraí teagmhála, uimhreacha gutháin, cuntais bhainc, eochracha agus pasfhocail, agus catagóirí speisialta sonraí pearsanta. Tarlaíonn sé seo go hiomlán ar an ngléas seo: ní sheoltar aon rud, agus ní thaispeántar an luach a aimsíodh in aon fhógra.',
  'De controle garandeert niet dat alles wordt gevonden; ze verkleint de kans dat er persoonsgegevens onbedoeld uitlekken.':
      'Ní ráthaíonn an tseiceáil go bhfaightear gach rud; laghdaíonn sí an seans go sceithfí sonraí pearsanta gan chuimhneamh.',
  'Tekst in afbeeldingen blijft buiten beeld, gelinkte bestanden worden niet geopend, en gegevens zonder herkenbaar patroon herkent geen enkele scanner. Een dia zonder meldingen is een dia waarin wíj niets hebben gevonden, niet een dia waarvan vaststaat dat er niets in staat. Wat je deelt, blijft jouw beslissing en jouw verantwoordelijkheid.':
      'Fanann téacs laistigh d\'íomhánna as radharc, ní osclaítear comhaid nasctha, agus ní aithníonn scanóir ar bith sonraí gan phatrún inaitheanta. Is sleamhnán é sleamhnán gan torthaí nach bhfuair *muidne* aon rud air — ní sleamhnán é a cruthaíodh nach bhfuil aon rud air. Is leatsa an cinneadh agus an fhreagracht faoina roinneann tú.',
  'telefoonnummer': 'uimhir ghutháin',
  'Voor wie is deze export?': 'Cé dó an t-easpórtáil seo?',
  'Volledig': 'Iomlán',
  'Geredigeerd': 'Folaithe',
  'Voor de opdrachtgever of auditor: alleen wat je zelf op "weglaten" hebt gezet, gaat eruit. De rest blijft leesbaar, zodat een derde partij de bevindingen kan controleren.':
      'Don chliant nó don iniúchóir: ní bhaintear ach an rud a shocraigh tú mar "fág ar lár". Fanann an chuid eile inléite, ionas gur féidir le tríú páirtí na torthaí a fhíorú.',
  'Voor de bredere kring: alles wat de controle vindt gaat eruit, ook op slides die je hebt geaccepteerd. Het bestand krijgt "-geredigeerd" in de naam.':
      'Do lucht féachana níos leithne: baintear gach a n-aimsíonn an tseiceáil, fiú ar shleamhnáin ar ghlac tú leo. Faigheann an comhad "-geredigeerd" ina ainm.',
  'tabel met persoonsgegevens (rijen×kolommen)':
      'tábla sonraí pearsanta (sraitheanna×colúin)',
