  'toegangstoken in een link': 'comharthán rochtana i nasc',
  'persoonsgegeven in een link': 'sonraí pearsanta i nasc',
  'deellink met ingebakken toegang': 'nasc comhroinnte le rochtain ionsuite',
  'e-mailadres in een link': 'seoladh ríomhphoist i nasc',
  'ingesloten afbeelding — wij kunnen er niet in kijken':
      'íomhá leabaithe — ní féidir linn breathnú isteach inti',
  'Je eigen gegevens': 'Do shonraí féin',
  'Eén per regel: je naam, e-mailadres, telefoonnummer of het domein van je organisatie. Wat hier staat wordt niet gemeld en niet geredigeerd — het is de afzender, geen bevinding. Een domein (example.org) dekt elk adres eronder.':
      'Ceann sa líne: d\'ainm, do sheoladh ríomhphoist, d\'uimhir ghutháin nó fearann d\'eagraíochta. Ní thuairiscítear ná ní fholaítear a bhfuil anseo — is é an seoltóir é, ní toradh. Clúdaíonn fearann (example.org) gach seoladh faoi.',
  'Bij onafgehandelde persoonsgegevens': 'Le sonraí pearsanta gan réiteach',
  'Export afgebroken vanwege privacybevindingen.':
      'Cuireadh an t-easpórtáil ar ceal mar gheall ar thorthaí príobháideachais.',
  'Export blokkeren': 'Cuir bac ar easpórtáil',
  'Export geblokkeerd': 'Easpórtáil bactha',
  'Export geblokkeerd: er staan persoonsgegevens in dit deck waarvoor nog geen keuze is gemaakt.':
      'Easpórtáil bactha: tá sonraí pearsanta sa láithreoireacht seo nár shocraigh tú fúthu fós.',
  'Kies per slide wat er moet gebeuren, of exporteer bewust zoals het is.':
      'Roghnaigh in aghaidh an tsleamhnáin cad ba cheart tarlú, nó easpórtáil d\'aon ghnó mar atá.',
  'Maak per slide een keuze (accepteren, waarschuwen of weglaten) voordat je exporteert. Dit is zo ingesteld bij Beveiliging.':
      'Déan rogha in aghaidh an tsleamhnáin (glac leis, tabhair rabhadh nó fág ar lár) sula n-easpórtálann tú. Socraítear é seo faoi Slándáil.',
  'Niets doen': 'Ná déan faic',
  'Persoonsgegevens in dit deck': 'Sonraí pearsanta sa láithreoireacht seo',
  'Verder in dit deck:': 'In áiteanna eile sa láithreoireacht seo:',
  'Waarschuwen vóór export': 'Tabhair rabhadh roimh easpórtáil',
  'bevinding(en) zonder keuze.': 'toradh/torthaí gan rogha.',
  'geaccepteerd': 'glactha',
  'geredigeerd': 'folaithe',
  'met waarschuwing': 'le rabhadh',
  'Deze regel nooit meer melden': 'Ná tuairiscigh an riail seo arís',
  'politieke opvatting': 'tuairim pholaitiúil',
  'etnische afkomst': 'bunús eitneach',
  'seksuele geaardheid': 'claonadh gnéasach',
  ' Op deze slide staat ook een identificerend gegeven, dus dit is herleidbaar tot een persoon.':
      ' Tá sonra aitheantais ar an sleamhnán seo freisin, mar sin tá sé inrianaithe chuig duine.',
  'Bijzonder persoonsgegeven (AVG art. 9/10)':
      'Catagóir speisialta sonraí pearsanta (RGCS airt. 9/10)',
  'gezondheidsgegeven': 'sonraí sláinte',
  'strafrechtelijk gegeven': 'sonraí coiriúla',
  'religie of levensovertuiging': 'reiligiún nó creideamh',
  'vakbondslidmaatschap': 'ballraíocht cheardchumainn',
  'biometrisch gegeven': 'sonraí bithmhéadracha',
  'genetisch gegeven': 'sonraí géiniteacha',
  'parketnummer': 'uimhir cháis ionchúisimh',
  'nationaal identificatienummer': 'uimhir aitheantais náisiúnta',
  'Mogelijk geheim': 'Rún féideartha',
  'sleutel of token': 'eochair nó comharthán',
  'private sleutel': 'eochair phríobháideach',
  'toegangstoken (JWT)': 'comharthán rochtana (JWT)',
  'databaseverbinding met wachtwoord': 'nasc bunachair sonraí le pasfhocal',
  'wachtwoord in klare tekst': 'pasfhocal i ngnáth-théacs',
  'Afbreken': 'Cealaigh',
  'Afgebroken. Er is niets half achtergebleven.':
      'Cealaithe. Níor fágadh aon rud leathdhéanta.',
  'Bijwerken': 'Nuashonraigh',
  'Binnenhalen…': 'Á íoslódáil…',
  'CVE\'s': 'CVE',
  'Database ophalen': 'Faigh an bunachar sonraí',
  'De CVE-lijst kon niet worden opgehaald. Controleer je verbinding en probeer het opnieuw; een half binnengehaalde lijst is weggegooid.':
      'Níorbh fhéidir an liosta CVE a fháil. Seiceáil do cheangal agus bain triail eile as; caitheadh liosta leathíoslódáilte i leataobh.',
  'De nieuwste uitgave opzoeken…': 'Ag cuardach an eisiúint is déanaí…',
  'Dit is een grote download: ruim 500 MB binnenhalen, tijdelijk zo\'n 1,5 GB schijfruimte, en afhankelijk van je verbinding en apparaat al gauw tien tot dertig minuten werk. Daarna blijft er een index van enkele honderden megabytes staan. Op een verbinding die per megabyte betaalt, doe je dit liever niet.':
      'Íoslódáil mhór atá anseo: breis is 500 MB le tarraingt anuas, timpeall 1,5 GB spás diosca go sealadach, agus ag brath ar do cheangal is ar do ghléas, deich go tríocha nóiméad oibre go héasca. Ina dhiaidh sin fanann innéacs cúpla céad megabyte. Ar cheangal a ghearrann táille de réir an mhegabyte, b\'fhearr gan é seo a dhéanamh.',
  'Er was te weinig schijfruimte. De opbouw vraagt tijdelijk ruim 1,5 GB.':
      'Ní raibh go leor spáis dhiosca ann. Teastaíonn breis is 1,5 GB go sealadach chun é a thógáil.',
  'Het opgehaalde archief was niet wat we verwachtten en is geweigerd. Er is niets geïnstalleerd.':
      'Níorbh é an chartlann a fuarthas an ceann a rabhthas ag súil leis agus diúltaíodh di. Níor suiteáladh aon rud.',
  'Indexeren…': 'Á innéacsú…',
  'Lokaal beschikbaar — opzoeken gebeurt offline, er gaat geen zoekterm naar buiten.':
      'Ar fáil go háitiúil — déantar cuardaigh as líne, ní fhágann téarma cuardaigh ar bith an gléas.',
  'Lokale CVE-database': 'Bunachar sonraí CVE áitiúil',
  'Met de CVE-lijst op je eigen apparaat blijft het opzoeken hier: er gaat geen zoekterm meer naar een server, en niemand kan zien welk lek je onderzoekt.':
      'Leis an liosta CVE ar do ghléas féin, fanann na cuardaigh anseo: ní théann téarma cuardaigh ar bith chuig freastalaí a thuilleadh, agus ní féidir le duine ar bith a fheiceáil cén leochaileacht atá á scrúdú agat.',
  'Uitpakken…': 'Á bhaint amach…',
  'Zet de volledige CVE-lijst op dit apparaat, zodat opzoeken offline gebeurt en je zoekterm nergens heen gaat. De database komt van CVE List V5 (het officiële CVE-programma, via GitHub).':
      'Cuir an liosta CVE iomlán ar an ngléas seo, ionas go ndéanfar cuardaigh as líne agus nach dtéann do théarma cuardaigh áit ar bith. Tagann an bunachar sonraí ó CVE List V5 (an clár oifigiúil CVE, trí GitHub).',
  'Wat er lokaal beschikbaar is': 'A bhfuil ar fáil go háitiúil',
  'Nu bijwerken': 'Nuashonraigh anois',
  'Gegevens lokaal beschikbaar — het opzoeken gebeurt op dit apparaat, er gaat niets naar buiten.':
      'Sonraí ar fáil go háitiúil — déantar cuardaigh ar an ngléas seo; ní fhágann aon rud é.',
  'Zwakheden (CWE)': 'Laigí (CWE)',
  'Testgevallen (WSTG)': 'Cásanna tástála (WSTG)',
  'MIAUW-eisen': 'Riachtanais MIAUW',
  'CVSS-scoretabel': 'Tábla scór CVSS',
  'Bevindingsjablonen': 'Teimpléid aimsithe',
  'Zoek een instelling': 'Cuardaigh socrú',
  'Geen instelling gevonden': 'Níor aimsíodh aon socrú',
  'Je zoekterm gaat naar de ingestelde CVE-mirror, en als die niets vindt ook naar ENISA en MITRE. Wie die servers beheert, kan daaruit afleiden naar welk specifiek lek je zoekt — en dus welk lek je onderzoekt.':
      'Téann do théarma cuardaigh chuig an scáthán CVE atá cumraithe, agus mura bhfaigheann sé sin aon rud, chuig ENISA agus MITRE freisin. Is féidir leo siúd a riarann na freastalaithe sin a thuiscint cén leochaileacht ar leith atá á lorg agat — agus mar sin cén leochaileacht atá á scrúdú agat.',
  'Accepteren': 'Glac leis',
  'Accepteren + waarschuwen': 'Glac leis + tabhair rabhadh',
  'Accepteren: de gegevens horen hier en de melding verdwijnt. Accepteren + waarschuwen: de ontvanger ziet een badge dat er persoonsgegevens op de slide staan. Weglaten: de gevonden gegevens worden onleesbaar gemaakt op het scherm en in de export — je markdown-bestand houdt de oorspronkelijke tekst.':
      'Glac leis: baineann na sonraí leis an áit seo agus imíonn an fógra. Glac leis + tabhair rabhadh: feiceann an faighteoir suaitheantas go bhfuil sonraí pearsanta ar an sleamhnán. Fág ar lár: déantar na sonraí a aimsíodh doléite ar an scáileán agus san easpórtáil — coinníonn do chomhad Markdown an téacs bunaidh.',
  'Alleen melden': 'Tuairiscigh amháin',
  'PERSOONSGEGEVENS': 'SONRAÍ PEARSANTA',
  'Volg de presentatie': 'Lean an láithreoireacht',
  'Weglaten uit tonen en exporteren':
      'Fág ar lár ón taispeáint agus ón easpórtáil',
  ' Overweeg dit te redigeren met [[dubbele blokhaken]].':
      ' Smaoinigh ar é a fholú le [[lúibíní cearnacha dúbailte]].',
  ' Zonder context in de tekst is dit mogelijk geen persoonsgegeven.':
      ' Gan comhthéacs sa téacs, seans nach sonraí pearsanta é seo ar chor ar bith.',
  'Leest je dia\'s na op identificatienummers, contactgegevens en andere privacygevoelige gegevens, en meldt ze bij de kwaliteitscontrole. Dit gebeurt volledig op dit apparaat; er wordt niets verstuurd. Het is een hulpmiddel, geen garantie: tekst in afbeeldingen en gegevens zonder herkenbaar patroon blijven buiten beeld.':
      'Scrúdaíonn sé do shleamhnáin le haghaidh uimhreacha aitheantais, sonraí teagmhála agus sonraí íogaire príobháideachais eile, agus tuairiscíonn sé iad sa seiceáil cáilíochta. Tarlaíonn sé seo go hiomlán ar an ngléas seo; ní sheoltar aon rud. Is áis é, ní ráthaíocht: fanann téacs laistigh d\'íomhánna agus sonraí gan patrún inaitheanta as radharc.',
  'Mogelijk persoonsgegeven': 'Sonraí pearsanta féideartha',
  'Privacycontrole': 'Seiceáil príobháideachais',
  'Waarschuw bij mogelijke persoonsgegevens':
      'Tabhair rabhadh faoi shonraí pearsanta féideartha',
  'burgerservicenummer (BSN)': 'uimhir sheirbhíse saoránach (BSN)',
  'bankrekeningnummer (IBAN)': 'uimhir chuntais bhainc (IBAN)',
  'e-mailadres': 'seoladh ríomhphoist',
  'De TSA-handtekening is niet in-app geverifieerd; alleen de hash komt overeen.':
      'Ní fhíoraítear síniú an TSA san aip; ní mheaitseálann ach an hais.',
  'Extern': 'Seachtrach',
  'Van een externe URL opgehaald; het openen heeft die server benaderd.':
      'Aisghabhadh ó URL seachtrach; rinne an oscailt teagmháil leis an bhfreastalaí sin.',
  'AI-assistentie (staat standaard uit): kies je een zelf-gehoste of cloud-backend, dan worden de teksten of afbeeldingen die je laat verwerken naar dat adres gestuurd. Wat je hebt geredigeerd, gaat er eerst uit. Een lokaal AI-model op dit apparaat verstuurt niets.':
      'Cúnamh IS (múchta de réir réamhshocraithe): má roghnaíonn tú inneall féin-óstáilte nó néalbhunaithe, seoltar na téacsanna nó na híomhánna a phróiseálann tú chuig an seoladh sin. Baintear an rud a rinne tú a fholú ar dtús. Ní sheolann samhail IS áitiúil ar an ngléas seo faic.',
  'Gegevens weglaten (redactie)': 'Sonraí a fhágáil ar lár (folú)',
  'Zet je tekst tussen dubbele blokhaken, zoals [[het adres]], dan laat OciDeck die weg uit alles wat je toont en exporteert. Op de dia, in de presentatie, in de PDF, de PowerPoint en de HTML verschijnen alleen blokken.':
      'Cuir téacs idir lúibíní cearnacha dúbailte, mar [[an seoladh]], agus fágfaidh OciDeck ar lár é as gach a dtaispeánann tú agus a easpórtálann tú. Ar an sleamhnán, sa láithreoireacht, sa PDF, sa PowerPoint agus san HTML, ní fheicfear ach bloic.',
  'Weggelaten is écht weggelaten, niet afgedekt. De tekst zit niet als onzichtbare laag onder een zwart balkje in de PDF, niet in de sprekersnotities van de PowerPoint, en niet in de broncode van de HTML. Wie het bestand openmaakt, kan er niets uit terughalen.':
      'Ciallaíonn fágtha ar lár go bhfuil sé fágtha ar lár i ndáiríre, ní hé go bhfuil sé clúdaithe. Níl an téacs ina shraith dhofheicthe faoi bharra dubh sa PDF, ná i nótaí cainteora an PowerPoint, ná i gcód foinseach an HTML. An té a osclaíonn an comhad, ní féidir leis aon rud a bhaint as.',
  'Je eigen bestand verandert niet. De oorspronkelijke tekst blijft in je markdown staan; redactie geldt alleen voor wat je deelt. Zo houd je je eigen gegevens.':
      'Ní athraíonn do chomhad féin. Fanann an téacs bunaidh i do mharcdown; ní bhaineann an folú ach leis an méid a roinneann tú. Mar sin coinníonn tú do shonraí féin.',
  'map/presentatie': 'fillteán/cur-i-láthair',
  'Gekoppelde test': 'Tástáil nasctha',
  'Maak eerst een checklist voor dit scope-object.':
      'Cruthaigh seicliosta don réad scóipe seo ar dtús.',
